EXEC model.declare_transformation @namespace = N'sidefx:capability:admit-api-run', @declared_id = N'admit-api-run-carry',
  @semantics_json = N'{"id":"admit-api-run-carry","expression":{"op":"path","path":""}}';
EXEC model.declare_transformation @namespace = N'sidefx:capability:admit-api-run', @declared_id = N'admit-api-run-complete-prepare',
  @semantics_json = N'{"id":"admit-api-run-complete-prepare","expression":{"op":"let","bindings":{"executeEntry":{"op":"find","from":{"op":"path","path":""},"as":"entry","where":{"op":"equals","left":{"op":"path","from":"entry","path":"slotId"},"right":{"op":"literal","value":"execute"}}},"carryEntry":{"op":"find","from":{"op":"path","path":""},"as":"entry","where":{"op":"equals","left":{"op":"path","from":"entry","path":"slotId"},"right":{"op":"literal","value":"carry"}}}},"value":{"op":"let","bindings":{"executed":{"op":"path","from":"executeEntry","path":"settlement.outcomeEnvelope.payload"},"carried":{"op":"path","from":"carryEntry","path":"settlement.outcomeEnvelope.payload"}},"value":{"op":"if","when":{"op":"equals","left":{"op":"type","value":{"op":"path","from":"carried","path":"runId"}},"right":{"op":"literal","value":"string"}},"then":{"op":"object","fields":{"executionTarget":{"op":"literal","value":"sql-database-reader"},"executionNamespace":{"op":"literal","value":"sidefx:capabilities"},"executionScenario":{"op":"literal","value":"sql-database-reader"},"inputType":{"op":"literal","value":"json"},"dispatchRequest":{"op":"object","fields":{"dataSource":{"op":"literal","value":"sfx-identity-database"},"statement":{"op":"literal","value":"SET NOCOUNT ON; DECLARE @r TABLE(trace_complete bit, material_digest binary(32)); DECLARE @run_id varchar(128) = JSON_VALUE(@input, ''$.runId''); DECLARE @writer_id varchar(64) = ''sfx-api''; DECLARE @run_json nvarchar(max) = JSON_QUERY(@input, ''$.run''); DECLARE @output_json nvarchar(max) = JSON_QUERY(@input, ''$.output''); DECLARE @latest_cursor bigint = 0; INSERT @r EXEC evidence.complete_run @run_id = @run_id, @writer_id = @writer_id, @run_json = @run_json, @graph_json = NULL, @output_json = @output_json, @latest_cursor = @latest_cursor; SELECT (SELECT N''COMPLETED'' AS status, @run_id AS runId, JSON_VALUE(@run_json, ''$.state'') AS state, JSON_VALUE(@input, ''$.admittedAt'') AS admittedAt, r.trace_complete AS traceComplete FROM @r r FOR JSON PATH, WITHOUT_ARRAY_WRAPPER) AS value;"},"resultColumn":{"op":"literal","value":"value"},"input":{"op":"object","fields":{"runId":{"op":"path","from":"carried","path":"runId"},"admittedAt":{"op":"path","from":"carried","path":"admittedAt"},"run":{"op":"object","fields":{"runId":{"op":"path","from":"carried","path":"runId"},"state":{"op":"literal","value":"completed"},"capability":{"op":"object","fields":{"object":{"op":"literal","value":"capability"},"operation":{"op":"literal","value":"invoke"},"subject":{"op":"path","from":"carried","path":"admission.subject"}}},"exitCode":{"op":"literal","value":0},"partial":{"op":"literal","value":false},"output":{"op":"object","fields":{"available":{"op":"literal","value":true}}}}},"output":{"op":"path","from":"executed","path":"result"}}}}}}},"else":{"op":"object","fields":{"executionTarget":{"op":"literal","value":"answer-api-response"},"executionNamespace":{"op":"literal","value":"sidefx:capabilities"},"executionScenario":{"op":"literal","value":"answer-api-response"},"inputType":{"op":"literal","value":"json"},"dispatchRequest":{"op":"path","from":"executed","path":"result"}}}}}}}';
EXEC model.declare_transformation @namespace = N'sidefx:capability:admit-api-run', @declared_id = N'admit-api-run-answer',
  @semantics_json = N'{"id":"admit-api-run-answer","expression":{"op":"if","when":{"op":"equals","left":{"op":"path","path":"result.contractId"},"right":{"op":"literal","value":"api-response.v1"}},"then":{"op":"path","path":"result"},"else":{"op":"if","when":{"op":"equals","left":{"op":"type","value":{"op":"path","path":"result.value"}},"right":{"op":"literal","value":"string"}},"then":{"op":"let","bindings":{"parsed":{"op":"try-parse-json","value":{"op":"path","path":"result.value"},"stripBom":true}},"value":{"op":"path","from":"parsed","path":"value"}},"else":{"op":"path","path":"result"}}}}';

EXEC model.apply_capability_from_dsl @document = N'{"contractId":"capability-from-dsl-change.v1","source":"capability admit-api-run\nintent: Admit a run of a declared capability through the declared API: the run store of the sfx-identity database registers it under the caller session and mints its run id, the kernel runs the capability, and the store completes the run with its outcome; a carry leg brings the run id to the completion.\noutcome: status COMPLETED with the run id and its state; a refused registration answers its refusal\ninquiry: Which run did this admission create?\ninput contract admit-api-run.v1 {\"type\":[\"object\",\"array\"]}\noutput contract admit-api-run.v1 {\"type\":[\"object\",\"array\"]}\ncli display outcome as json\nscenario admit-api-run root\ngiven: an admission (object, operation, subject, namespace, input) with the caller principal and session\nwhen: the run store registers the run\nthen: the run id and the admission go to both legs\noperation admit-api-run.prepare kind invoke-port port admit-api-run-prepare\noperation admit-api-run.register kind invoke-port port admit-api-run-register\noperation admit-api-run.lift kind invoke-port port admit-api-run-lift\nplatform bind admit-api-run-prepare\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-prepare\"}\nplatform bind admit-api-run-register\nplatform: generic-capability-invocation.v1\nconfig: {\"providerId\":\"sql-database-reader\",\"authoritySource\":\"DATABASE\",\"capabilityIdPath\":\"executionTarget\",\"namespacePath\":\"executionNamespace\",\"scenarioPath\":\"executionScenario\",\"requestPath\":\"dispatchRequest\",\"resultPath\":\"result\",\"lineageMode\":\"retain-nested-execution\"}\nplatform bind admit-api-run-lift\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-lift\"}\nscenario admit-api-run-execute\ngiven: the registered run and its admission\nwhen: the kernel runs the admitted capability\nthen: its outcome settles the execute slot\noperation admit-api-run-execute.prepare kind invoke-port port admit-api-run-execute-prepare\noperation admit-api-run-execute.run kind invoke-port port admit-api-run-execute-run\nplatform bind admit-api-run-execute-prepare\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-execute-prepare\"}\nplatform bind admit-api-run-execute-run\nplatform: generic-capability-invocation.v1\nconfig: {\"providerId\":\"generic-capability-invocation\",\"authoritySource\":\"DATABASE\",\"capabilityIdPath\":\"executionTarget\",\"namespacePath\":\"executionNamespace\",\"scenarioPath\":\"executionScenario\",\"requestPath\":\"dispatchRequest\",\"resultPath\":\"result\",\"lineageMode\":\"retain-nested-execution\"}\nscenario admit-api-run-carry\ngiven: the registered run\nwhen: the run id is carried\nthen: it settles the carry slot\noperation admit-api-run-carry.carry kind invoke-port port admit-api-run-carry\nplatform bind admit-api-run-carry\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-carry\"}\nscenario admit-api-run-complete\ngiven: the execute and carry slots\nwhen: the run store completes the run with its outcome\nthen: the outcome is the completed run\noperation admit-api-run-complete.prepare kind invoke-port port admit-api-run-complete-prepare\noperation admit-api-run-complete.complete kind invoke-port port admit-api-run-complete-complete\noperation admit-api-run-complete.answer kind invoke-port port admit-api-run-answer\nplatform bind admit-api-run-complete-prepare\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-complete-prepare\"}\nplatform bind admit-api-run-complete-complete\nplatform: generic-capability-invocation.v1\nconfig: {\"providerId\":\"generic-capability-invocation\",\"authoritySource\":\"DATABASE\",\"capabilityIdPath\":\"executionTarget\",\"namespacePath\":\"executionNamespace\",\"scenarioPath\":\"executionScenario\",\"requestPath\":\"dispatchRequest\",\"resultPath\":\"result\",\"lineageMode\":\"retain-nested-execution\"}\nplatform bind admit-api-run-answer\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-answer\"}\nbroadcast admit-api-run to admit-api-run-execute,admit-api-run-carry\njoin admit-api-run-complete from admit-api-run-execute,admit-api-run-carry","isMcpTooling":false}';

COMMIT;
